import{_ as i,r as o,o as r,c as a,e as t,a as l,s as c}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Deploying Your Site - October CMS User Guide","titleTemplate":false,"description":"Deploy your site using Git or FTP: two approaches for different hosting setups","frontmatter":{"subtitle":"Deploy your site using Git or FTP: two approaches for different hosting setups"},"headers":[{"level":2,"title":"Option 1: Git-Based Deployment (Recommended)","slug":"option-1-git-based-deployment-recommended","link":"#option-1-git-based-deployment-recommended","children":[{"level":3,"title":"Push Your Project to Git","slug":"push-your-project-to-git","link":"#push-your-project-to-git","children":[]},{"level":3,"title":"Clone and Set Up on the Server","slug":"clone-and-set-up-on-the-server","link":"#clone-and-set-up-on-the-server","children":[]},{"level":3,"title":"Set Up the Public Directory with Mirror","slug":"set-up-the-public-directory-with-mirror","link":"#set-up-the-public-directory-with-mirror","children":[]},{"level":3,"title":"Updating Your Site","slug":"updating-your-site","link":"#updating-your-site","children":[]}]},{"level":2,"title":"Option 2: FTP Upload","slug":"option-2-ftp-upload","link":"#option-2-ftp-upload","children":[{"level":3,"title":"Install on the Server First","slug":"install-on-the-server-first","link":"#install-on-the-server-first","children":[]},{"level":3,"title":"Upload Your App Files","slug":"upload-your-app-files","link":"#upload-your-app-files","children":[]},{"level":3,"title":"Run Migrations","slug":"run-migrations","link":"#run-migrations","children":[]},{"level":3,"title":"Configure Nginx","slug":"configure-nginx","link":"#configure-nginx","children":[]}]},{"level":2,"title":"Post-Deployment Checklist","slug":"post-deployment-checklist","link":"#post-deployment-checklist","children":[]},{"level":2,"title":"Next Steps","slug":"next-steps","link":"#next-steps","children":[]}],"relativePath":"user-guide/quickstart/deployment/deploying-your-site.md","filePath":"user-guide/quickstart/deployment/deploying-your-site.md"}'),p={name:"user-guide/quickstart/deployment/deploying-your-site.md"};function d(u,e,h,g,m,y){const n=o("pre-heading"),s=o("post-heading");return r(),a("div",null,[t(n),e[0]||(e[0]=l("h1",null,"Deploying Your Site",-1)),t(s),e[1]||(e[1]=c(`<p>You have built your site and <a href="./preparing-for-production.html">prepared it for production</a>. Now let&#39;s get it onto a live server. There are two main approaches: Git-based deployment for servers with SSH access, and FTP upload for shared hosting.</p><h2 id="option-1-git-based-deployment-recommended"><a href="#option-1-git-based-deployment-recommended" class="header-anchor">#</a> Option 1: Git-Based Deployment (Recommended)</h2><p>If you have SSH access to your server, Git gives you version control, easy rollbacks, and a clean deployment workflow.</p><h3 id="push-your-project-to-git"><a href="#push-your-project-to-git" class="header-anchor">#</a> Push Your Project to Git</h3><p>Initialize a repository and push to GitHub, GitLab, or Bitbucket:</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token function">git</span> init
<span class="token function">git</span> <span class="token function">add</span> <span class="token builtin class-name">.</span>
<span class="token function">git</span> commit <span class="token parameter variable">-m</span> <span class="token string">&quot;Initial commit&quot;</span>
<span class="token function">git</span> remote <span class="token function">add</span> origin https://github.com/your-username/your-project.git
<span class="token function">git</span> push <span class="token parameter variable">-u</span> origin main
</code></pre></div><p>You will notice that <code>modules/</code> and <code>vendor/</code> are already excluded in <code>.gitignore</code>. These are framework dependencies provided by Composer. The rest of the project (including your <code>app/</code>, <code>plugins/</code>, and <code>themes/</code> directories) is what makes up your site.</p><div class="custom-block warning"><p>Never commit your <code>.env</code> file to version control. It contains sensitive credentials. October CMS excludes it by default via <code>.gitignore</code>. You will create a separate <code>.env</code> file on your production server.</p></div><h3 id="clone-and-set-up-on-the-server"><a href="#clone-and-set-up-on-the-server" class="header-anchor">#</a> Clone and Set Up on the Server</h3><p>SSH into your server, clone the project, and install dependencies:</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token function">ssh</span> user@your-server.com
<span class="token builtin class-name">cd</span> /var/www
<span class="token function">git</span> clone https://github.com/your-username/your-project.git your-site
<span class="token builtin class-name">cd</span> your-site
</code></pre></div><p>Copy your <code>auth.json</code> file to the server (it contains your license key for Composer):</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token comment"># Run this from your local machine</span>
<span class="token function">scp</span> auth.json user@your-server.com:/var/www/your-site/auth.json
</code></pre></div><p>Then install dependencies and run migrations on the server:</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token function">composer</span> <span class="token function">install</span> --no-dev
<span class="token function">cp</span> .env.example .env
<span class="token comment"># Edit .env with your production settings</span>
php artisan october:migrate
</code></pre></div><h3 id="set-up-the-public-directory-with-mirror"><a href="#set-up-the-public-directory-with-mirror" class="header-anchor">#</a> Set Up the Public Directory with Mirror</h3><p>For Git deployments, we recommend using the <code>october:mirror</code> command. This creates a <code>public/</code> directory and mirrors the necessary assets (like plugin and theme assets) into it. Point your web server&#39;s document root to this <code>public/</code> directory.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan october:mirror
</code></pre></div><div class="custom-block warning"><p>You need to run <code>october:mirror</code> again any time you install a new plugin or create a new theme, so the new assets get mirrored into the public directory.</p></div><h3 id="updating-your-site"><a href="#updating-your-site" class="header-anchor">#</a> Updating Your Site</h3><p>After the initial deployment, updates are straightforward:</p><ol><li>Push changes to your Git repository.</li><li>Pull them on the server: <code>git pull</code></li><li>Run <code>composer update</code> if dependencies changed.</li><li>Run <code>php artisan october:migrate</code> if there are new migrations.</li><li>Run <code>php artisan october:mirror</code> if you added new plugins or themes.</li></ol><h2 id="option-2-ftp-upload"><a href="#option-2-ftp-upload" class="header-anchor">#</a> Option 2: FTP Upload</h2><p>If you are on shared hosting without SSH, the simplest approach is to install October CMS on the server first, then upload your app files.</p><h3 id="install-on-the-server-first"><a href="#install-on-the-server-first" class="header-anchor">#</a> Install on the Server First</h3><ol><li>Download the <strong>Wizard Installer</strong> from octobercms.com.</li><li>Upload the installer zip to your server&#39;s web root via FTP.</li><li>Extract the zip on the server (most hosting control panels let you do this).</li><li>Visit the URL in your browser and follow the on-screen wizard to install October CMS with your production database.</li></ol><p>This gives you a clean October CMS installation on the server with all framework files in place.</p><h3 id="upload-your-app-files"><a href="#upload-your-app-files" class="header-anchor">#</a> Upload Your App Files</h3><p>Now upload just your custom files on top of the installation. Using your FTP client, upload:</p><ul><li><strong><code>themes/</code></strong>: your theme with layouts, pages, partials, and blueprints</li><li><strong><code>app/</code></strong>: your application code (if any)</li><li><strong><code>plugins/</code></strong>: any custom plugins (marketplace plugins can be installed through the backend)</li></ul><p>These three directories contain everything that makes your site unique. The rest of the framework is already installed.</p><h3 id="run-migrations"><a href="#run-migrations" class="header-anchor">#</a> Run Migrations</h3><p>If your host provides SSH or a terminal in the control panel, run:</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan october:migrate
</code></pre></div><p>If SSH is not available, October CMS handles migrations automatically when you first access the backend.</p><h3 id="configure-nginx"><a href="#configure-nginx" class="header-anchor">#</a> Configure Nginx</h3><p>If your hosting uses Nginx, copy the <code>nginx.conf</code> file from the October CMS project root and use it in your server block configuration. Apache servers work out of the box with the included <code>.htaccess</code> file.</p><h2 id="post-deployment-checklist"><a href="#post-deployment-checklist" class="header-anchor">#</a> Post-Deployment Checklist</h2><p>Once your site is live, verify everything works:</p><ul><li><strong>Visit the frontend.</strong> Browse your pages and check that images, styles, and content load correctly.</li><li><strong>Log into the backend.</strong> Go to <code>yoursite.com/admin</code> and confirm you can sign in.</li><li><strong>Test interactive features.</strong> Submit the contact form on a team member&#39;s profile and check that it works.</li><li><strong>Check for mixed content.</strong> If using HTTPS, make sure all assets load over HTTPS too.</li><li><strong>Set up backups.</strong> Configure automated backups for your files and database.</li></ul><h2 id="next-steps"><a href="#next-steps" class="header-anchor">#</a> Next Steps</h2><p>Your site is live. Continue to <a href="./what-next.html">Where to Go from Here</a> for ideas on what to build next, from exploring the demo theme to building plugins and selling products.</p>`,42))])}const b=i(p,[["render",d]]);export{v as __pageData,b as default};
